-- Normalise the status values written by the old checkout ('Pending').
update public.orders set status = lower(status) where status <> lower(status);

-- ---------------------------------------------------------------------------
-- Admin helper — used by every write policy below
-- ---------------------------------------------------------------------------
create or replace function public.is_admin()
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select exists (
    select 1 from public.profiles
    where id = auth.uid() and role = 'admin'
  );
$$;

-- Create a profile row for every new signup
create or replace function public.handle_new_user()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  insert into public.profiles (id, email, role)
  values (new.id, new.email, 'user')
  on conflict (id) do nothing;
  return new;
end;
$$;

drop trigger if exists on_auth_user_created on auth.users;
create trigger on_auth_user_created
  after insert on auth.users
  for each row execute function public.handle_new_user();

-- ---------------------------------------------------------------------------
-- Order placement — the only thing an anonymous visitor may write.
--
-- Prices, stock and totals are resolved here, server-side, so a tampered
-- browser cart cannot change what is charged. SECURITY DEFINER: the function
-- runs with the owner's rights, so anonymous users need no table grants.
-- ---------------------------------------------------------------------------
create or replace function public.place_order(
  p_customer jsonb,
  p_items jsonb,
  p_delivery text,
  p_payment text,
  p_gift_note text default null
)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_subtotal      numeric(12,2) := 0;
  v_shipping      numeric(12,2) := 0;
  v_total         numeric(12,2) := 0;
  v_customer_id   bigint;
  v_order_id      bigint;
  v_new_stock     integer;
  v_item          jsonb;
  v_product       public.products;
  v_qty           integer;
  v_name          text := nullif(trim(coalesce(p_customer->>'name', '')), '');
  v_phone         text := nullif(trim(coalesce(p_customer->>'phone', '')), '');
  v_address       text := trim(coalesce(p_customer->>'address', ''));
begin
  if v_name is null then
    raise exception 'Customer name is required';
  end if;
  if v_phone is null or length(regexp_replace(v_phone, '\D', '', 'g')) < 7 then
    raise exception 'A valid phone number is required';
  end if;
  if p_items is null or jsonb_typeof(p_items) <> 'array' or jsonb_array_length(p_items) = 0 then
    raise exception 'Your cart is empty';
  end if;
  if coalesce(p_payment, 'cod') not in ('cod', 'esewa', 'khalti', 'fonepay') then
    raise exception 'Unsupported payment method';
  end if;
  if coalesce(p_delivery, 'standard') not in ('standard', 'express') then
    raise exception 'Unsupported delivery method';
  end if;

  -- 1. Resolve every line from the catalogue and lock the rows
  for v_item in select * from jsonb_array_elements(p_items) loop
    v_qty := greatest(1, least(99, coalesce((v_item->>'qty')::integer, 1)));

    select * into v_product
    from public.products
    where id = (v_item->>'product_id')::bigint
    for update;

    if not found then
      raise exception 'Product % is no longer available', coalesce(v_item->>'product_id', '?');
    end if;
    if coalesce(v_product.stock, 0) < v_qty then
      raise exception 'Only % left in stock for %', coalesce(v_product.stock, 0), v_product.name;
    end if;

    v_subtotal := v_subtotal + (v_product.price * v_qty);
  end loop;

  v_shipping := case
    when v_subtotal >= 2000 then 0
    when p_delivery = 'express' then 250
    else 150
  end;
  v_total := v_subtotal + v_shipping;

  -- 2. Customer: reuse by phone, otherwise create
  select id into v_customer_id from public.customers where phone = v_phone limit 1;

  if v_customer_id is null then
    insert into public.customers (name, email, phone, address, notes, total_orders, total_spent)
    values (v_name, '', v_phone, v_address, coalesce(p_gift_note, ''), 1, v_total)
    returning id into v_customer_id;
  else
    update public.customers
       set name = coalesce(v_name, name),
           address = coalesce(nullif(v_address, ''), address),
           notes = coalesce(nullif(p_gift_note, ''), notes),
           total_orders = coalesce(total_orders, 0) + 1,
           total_spent = coalesce(total_spent, 0) + v_total
     where id = v_customer_id;
  end if;

  -- 3. Order
  insert into public.orders
    (customer_id, customer_name, subtotal, shipping, total, status, payment, shipping_address, date)
  values
    (v_customer_id, v_name, v_subtotal, v_shipping, v_total, 'pending', coalesce(p_payment, 'cod'), v_address, to_char(now(), 'YYYY-MM-DD'))
  returning id into v_order_id;

  -- 4. Line items, stock and history
  for v_item in select * from jsonb_array_elements(p_items) loop
    v_qty := greatest(1, least(99, coalesce((v_item->>'qty')::integer, 1)));

    select * into v_product from public.products where id = (v_item->>'product_id')::bigint;
    v_new_stock := greatest(0, coalesce(v_product.stock, 0) - v_qty);

    insert into public.order_items (order_id, product_id, name, price, qty, image)
    values (v_order_id, v_product.id, v_product.name, v_product.price, v_qty, v_product.image);

    update public.products
       set stock = v_new_stock,
           in_stock = (v_new_stock > 0)
     where id = v_product.id;

    insert into public.stock_history (product, product_name, type, change_amount, new_stock, date)
    values (v_product.name, v_product.name, 'Sold', -v_qty, v_new_stock, to_char(now(), 'YYYY-MM-DD'));
  end loop;

  return jsonb_build_object(
    'order_id', v_order_id,
    'order_number', 'TAH-' || lpad(v_order_id::text, 5, '0'),
    'subtotal', v_subtotal,
    'shipping', v_shipping,
    'total', v_total,
    'status', 'pending'
  );
end;
$$;

revoke all on function public.place_order(jsonb, jsonb, text, text, text) from public;
grant execute on function public.place_order(jsonb, jsonb, text, text, text) to anon, authenticated;

-- ---------------------------------------------------------------------------
-- Row level security
-- ---------------------------------------------------------------------------
alter table public.products      enable row level security;
alter table public.customers     enable row level security;
alter table public.orders        enable row level security;
alter table public.order_items   enable row level security;
alter table public.invoices      enable row level security;
alter table public.stock_history enable row level security;
alter table public.settings      enable row level security;
alter table public.profiles      enable row level security;

-- Remove any pre-existing policies first: policies are OR-ed together, so a
-- leftover "allow everyone" rule would keep customer rows readable.
do $$
declare
  policy_row record;
begin
  for policy_row in
    select schemaname, tablename, policyname
    from pg_policies
    where schemaname = 'public'
      and tablename in ('products', 'customers', 'orders', 'order_items',
                        'invoices', 'stock_history', 'settings', 'profiles')
  loop
    execute format('drop policy %I on %I.%I',
                   policy_row.policyname, policy_row.schemaname, policy_row.tablename);
  end loop;
end;
$$;

-- products: the whole world may read; only admins may write
drop policy if exists products_read on public.products;
create policy products_read on public.products
  for select to anon, authenticated using (true);

drop policy if exists products_admin_write on public.products;
create policy products_admin_write on public.products
  for all to authenticated using (public.is_admin()) with check (public.is_admin());

-- customer / order data: admins only. Guests write through place_order().
drop policy if exists customers_admin on public.customers;
create policy customers_admin on public.customers
  for all to authenticated using (public.is_admin()) with check (public.is_admin());

drop policy if exists orders_admin on public.orders;
create policy orders_admin on public.orders
  for all to authenticated using (public.is_admin()) with check (public.is_admin());

drop policy if exists order_items_admin on public.order_items;
create policy order_items_admin on public.order_items
  for all to authenticated using (public.is_admin()) with check (public.is_admin());

drop policy if exists invoices_admin on public.invoices;
create policy invoices_admin on public.invoices
  for all to authenticated using (public.is_admin()) with check (public.is_admin());

drop policy if exists stock_history_admin on public.stock_history;
create policy stock_history_admin on public.stock_history
  for all to authenticated using (public.is_admin()) with check (public.is_admin());

drop policy if exists settings_admin on public.settings;
create policy settings_admin on public.settings
  for all to authenticated using (public.is_admin()) with check (public.is_admin());

-- profiles: you can read your own row; admins can read all
drop policy if exists profiles_self_read on public.profiles;
create policy profiles_self_read on public.profiles
  for select to authenticated using (id = auth.uid() or public.is_admin());

drop policy if exists profiles_admin_write on public.profiles;
create policy profiles_admin_write on public.profiles
  for update to authenticated using (public.is_admin()) with check (public.is_admin());

